export const getPassage = (topic, duration, difficulty) => {
  // Convert duration to number
  const numDuration = parseInt(duration);
  
  // Get all passages for the duration, fallback to 60 if not found
  const durationPassages = PASSAGES[numDuration] || PASSAGES[60];
  
  // If random, just filter by duration and difficulty
  if (topic === 'random') {
    let matches = durationPassages.filter(p => p.difficulty === difficulty);
    if (matches.length === 0) matches = durationPassages;
    return matches[Math.floor(Math.random() * matches.length)];
  }

  // Fallback 1: Exact topic + duration + difficulty
  let matches = durationPassages.filter(p => p.topic === topic && p.difficulty === difficulty);
  
  // Fallback 2: Same topic + duration
  if (matches.length === 0) {
    matches = durationPassages.filter(p => p.topic === topic);
  }

  // Fallback 3: General + duration + difficulty
  if (matches.length === 0) {
    matches = durationPassages.filter(p => p.topic === 'general' && p.difficulty === difficulty);
  }

  // Fallback 4: General + duration
  if (matches.length === 0) {
    matches = durationPassages.filter(p => p.topic === 'general');
  }

  // Fallback 5: Anything matching duration
  if (matches.length === 0) {
    matches = durationPassages;
  }

  // Filter out recently used if there are multiple matches
  // A simple strategy is just to pick random from matches
  // The React component can handle tracking recent IDs
  return matches[Math.floor(Math.random() * matches.length)];
};
